*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-dark: #15295A;
  --charcoal: #1B2838;
  --teal: #00B4D8;
  --teal-dark: #0077B6;
  --green: #6CC24A;
  --dark-gray: #3C424B;
  --light-gray: #E8E8E8;
  --white: #FFFFFF;
  --text-muted: #A0AEC0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); background: var(--navy); color: var(--white); line-height: 1.6; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

/* Navigation */
.navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 42, 0.95); backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  padding: 0 2rem;
}
.nav-container {
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; height: 72px;
}
.nav-logo { font-size: 1.5rem; font-weight: 700; color: var(--white); display: flex; align-items: center; gap: 0.5rem; }
.nav-logo span { color: var(--teal); }
.nav-links { display: flex; align-items: center; gap: 2rem; }
.nav-dropdown { position: relative; }
.nav-dropdown-btn {
  background: none; border: none; color: var(--white); font-size: 0.95rem;
  cursor: pointer; display: flex; align-items: center; gap: 0.3rem; padding: 0.5rem 0;
  transition: color 0.2s;
}
.nav-dropdown-btn:hover { color: var(--teal); }
.nav-dropdown-btn svg { width: 12px; height: 12px; transition: transform 0.2s; }
.nav-dropdown:hover .nav-dropdown-btn svg { transform: rotate(180deg); }
.nav-dropdown-menu {
  position: absolute; top: 100%; left: 0; min-width: 200px;
  background: var(--charcoal); border-radius: 8px; padding: 0.5rem;
  opacity: 0; visibility: hidden; transform: translateY(10px);
  transition: all 0.2s; box-shadow: 0 10px 40px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.nav-dropdown-menu a {
  display: block; padding: 0.6rem 1rem; border-radius: 4px;
  transition: background 0.2s; font-size: 0.9rem;
}
.nav-dropdown-menu a:hover { background: rgba(0,180,216,0.15); color: var(--teal); }
.nav-cta {
  background: var(--teal); color: var(--navy); font-weight: 600;
  padding: 0.6rem 1.25rem; border-radius: 6px; border: none;
  cursor: pointer; font-size: 0.9rem; transition: background 0.2s;
}
.nav-cta:hover { background: var(--teal-dark); }
.mobile-menu-btn { display: none; background: none; border: none; color: var(--white); cursor: pointer; }

/* Hero */
.hero {
  min-height: 100vh; display: flex; align-items: center;
  background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  padding: 8rem 2rem 4rem; position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,180,216,0.12) 0%, transparent 60%);
}
.hero-container { max-width: 1400px; margin: 0 auto; width: 100%; display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.hero-content { position: relative; z-index: 1; }
.hero-badge {
  display: inline-block; background: rgba(0,180,216,0.15); color: var(--teal);
  padding: 0.4rem 1rem; border-radius: 20px; font-size: 0.85rem; font-weight: 500;
  margin-bottom: 1.5rem; border: 1px solid rgba(0,180,216,0.3);
}
.hero h1 { font-size: 3.5rem; font-weight: 800; line-height: 1.1; margin-bottom: 1.5rem; }
.hero h1 em { font-style: normal; color: var(--teal); }
.hero-subtitle { font-size: 1.2rem; color: var(--text-muted); margin-bottom: 2rem; max-width: 540px; }
.hero-buttons { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  background: var(--teal); color: var(--navy); font-weight: 600;
  padding: 0.9rem 1.75rem; border-radius: 6px; border: none;
  cursor: pointer; font-size: 1rem; transition: all 0.2s;
}
.btn-primary:hover { background: var(--teal-dark); transform: translateY(-2px); }
.btn-secondary {
  background: transparent; color: var(--white); font-weight: 600;
  padding: 0.9rem 1.75rem; border-radius: 6px; border: 1px solid rgba(255,255,255,0.3);
  cursor: pointer; font-size: 1rem; transition: all 0.2s;
}
.btn-secondary:hover { border-color: var(--teal); color: var(--teal); }
.hero-visual { position: relative; z-index: 1; }

/* Platform Ecosystem Diagram */
.platform-diagram {
  background: var(--charcoal); border-radius: 16px; padding: 2.5rem;
  border: 1px solid rgba(255,255,255,0.08);
}
.diagram-title { text-align: center; font-size: 1.1rem; color: var(--text-muted); margin-bottom: 2rem; text-transform: uppercase; letter-spacing: 2px; }
.diagram-nodes { display: flex; flex-direction: column; gap: 1.5rem; }
.diagram-row { display: flex; justify-content: center; gap: 1.5rem; flex-wrap: wrap; }
.diagram-node {
  background: var(--navy-dark); border: 1px solid rgba(0,180,216,0.3);
  border-radius: 10px; padding: 1rem 1.5rem; text-align: center;
  min-width: 180px; transition: all 0.3s;
}
.diagram-node:hover { border-color: var(--teal); transform: translateY(-3px); box-shadow: 0 8px 30px rgba(0,180,216,0.2); }
.diagram-node h4 { color: var(--teal); font-size: 0.9rem; margin-bottom: 0.3rem; }
.diagram-node p { font-size: 0.8rem; color: var(--text-muted); }
.diagram-connectors { display: flex; justify-content: center; padding: 0.5rem 0; }
.connector-line { width: 2px; height: 30px; background: linear-gradient(to bottom, var(--teal), transparent); }
.connector-branch { display: flex; gap: 2rem; }
.connector-h { width: 60px; height: 2px; background: linear-gradient(to right, transparent, var(--teal), transparent); }

/* Featured Banner */
.featured-banner {
  background: linear-gradient(90deg, var(--navy-dark), var(--charcoal));
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
  padding: 1.5rem 2rem;
}
.featured-inner {
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem;
}
.featured-label { color: var(--green); font-weight: 600; font-size: 0.9rem; text-transform: uppercase; letter-spacing: 1px; }
.featured-product { font-size: 1.2rem; font-weight: 700; }
.featured-tag { color: var(--text-muted); font-size: 0.9rem; }
.btn-learn {
  background: transparent; border: 1px solid var(--green); color: var(--green);
  padding: 0.5rem 1.25rem; border-radius: 6px; cursor: pointer; font-size: 0.9rem;
  transition: all 0.2s;
}
.btn-learn:hover { background: var(--green); color: var(--navy); }

/* Use Cases */
.use-cases { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.section-label { color: var(--teal); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 0.75rem; }
.section-title { font-size: 2.5rem; font-weight: 700; margin-bottom: 1rem; }
.section-desc { color: var(--text-muted); max-width: 700px; margin-bottom: 3rem; font-size: 1.05rem; }
.use-case-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1.5rem; }
.use-case-card {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s; cursor: pointer;
}
.use-case-card:hover { border-color: rgba(0,180,216,0.4); transform: translateY(-4px); box-shadow: 0 15px 40px rgba(0,0,0,0.3); }
.use-case-card h3 { font-size: 1.1rem; margin-bottom: 0.75rem; color: var(--white); }
.use-case-card p { color: var(--text-muted); font-size: 0.95rem; }

/* Industry Tabs */
.industry-tabs-section { padding: 4rem 2rem; background: var(--charcoal); }
.industry-tabs-container { max-width: 1400px; margin: 0 auto; }
.tabs-nav { display: flex; gap: 0; border-bottom: 1px solid rgba(255,255,255,0.1); margin-bottom: 2rem; flex-wrap: wrap; }
.tab-btn {
  background: none; border: none; color: var(--text-muted);
  padding: 1rem 1.5rem; cursor: pointer; font-size: 0.95rem;
  border-bottom: 2px solid transparent; transition: all 0.2s;
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active { color: var(--teal); border-bottom-color: var(--teal); }
.tab-content { display: none; animation: fadeIn 0.3s ease; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel { background: var(--navy); border-radius: 12px; padding: 2rem; }
.tab-panel h3 { font-size: 1.3rem; margin-bottom: 1rem; }
.tab-panel p { color: var(--text-muted); }

/* Company Culture */
.company-culture { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.culture-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.culture-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 2rem; }
.stat-box { text-align: center; padding: 1.5rem; background: var(--charcoal); border-radius: 10px; }
.stat-number { font-size: 2.5rem; font-weight: 700; color: var(--teal); }
.stat-label { font-size: 0.85rem; color: var(--text-muted); margin-top: 0.3rem; }

/* Renewables CTA */
.renewables-cta {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--charcoal) 100%);
  padding: 5rem 2rem; text-align: center;
}
.cta-inner { max-width: 800px; margin: 0 auto; }
.cta-inner h2 { font-size: 2.5rem; margin-bottom: 1rem; }
.cta-inner p { color: var(--text-muted); margin-bottom: 2rem; font-size: 1.1rem; }

/* Footer */
.footer { background: var(--navy); border-top: 1px solid rgba(255,255,255,0.08); padding: 4rem 2rem 2rem; }
.footer-grid { max-width: 1400px; margin: 0 auto; display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: 3rem; margin-bottom: 3rem; }
.footer-brand p { color: var(--text-muted); margin-top: 1rem; font-size: 0.9rem; max-width: 280px; }
.footer-col h4 { font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 1.25rem; color: var(--text-muted); }
.footer-col ul li { margin-bottom: 0.75rem; }
.footer-col ul li a { color: var(--white); font-size: 0.95rem; transition: color 0.2s; }
.footer-col ul li a:hover { color: var(--teal); }
.footer-bottom {
  max-width: 1400px; margin: 0 auto; padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem;
}
.footer-legal { color: var(--text-muted); font-size: 0.85rem; }
.footer-portals { display: flex; gap: 1.5rem; }
.footer-portals a { color: var(--teal); font-size: 0.85rem; }

/* Cookie Banner */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 999;
  background: var(--charcoal); border-top: 1px solid rgba(255,255,255,0.1);
  padding: 1.25rem 2rem; display: none; align-items: center;
  justify-content: space-between; gap: 2rem; flex-wrap: wrap;
}
.cookie-banner.show { display: flex; }
.cookie-banner p { font-size: 0.9rem; color: var(--text-muted); }
.cookie-buttons { display: flex; gap: 1rem; }
.cookie-btn {
  padding: 0.5rem 1.25rem; border-radius: 6px; cursor: pointer;
  font-size: 0.9rem; transition: all 0.2s;
}
.cookie-accept { background: var(--teal); border: none; color: var(--navy); font-weight: 600; }
.cookie-decline { background: transparent; border: 1px solid rgba(255,255,255,0.3); color: var(--white); }

/* Platform Overview Page */
.page-hero {
  padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  text-align: center; position: relative;
}
.page-hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 50% 30%, rgba(0,180,216,0.1) 0%, transparent 60%);
}
.page-hero h1 { font-size: 3rem; font-weight: 800; margin-bottom: 1rem; position: relative; }
.page-hero p { font-size: 1.15rem; color: var(--text-muted); max-width: 600px; margin: 0 auto; position: relative; }

/* Benefits Grid */
.benefits-section { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.benefits-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; }
.benefit-card {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s;
}
.benefit-card:hover { border-color: rgba(0,180,216,0.4); }
.benefit-icon { width: 48px; height: 48px; background: rgba(0,180,216,0.15); border-radius: 10px; display: flex; align-items: center; justify-content: center; margin-bottom: 1rem; }
.benefit-icon svg { width: 24px; height: 24px; color: var(--teal); }
.benefit-card h3 { font-size: 1.1rem; margin-bottom: 0.5rem; }
.benefit-card p { color: var(--text-muted); font-size: 0.9rem; }

/* Stats Section */
.stats-section { padding: 4rem 2rem; background: var(--charcoal); }
.stats-container { max-width: 1000px; margin: 0 auto; display: flex; justify-content: center; gap: 4rem; flex-wrap: wrap; }
.stat-circle {
  width: 180px; height: 180px; border-radius: 50%;
  background: var(--navy); border: 3px solid var(--teal);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  position: relative;
}
.stat-circle::before {
  content: ''; position: absolute; inset: -8px;
  border-radius: 50%; border: 1px solid rgba(0,180,216,0.2);
}
.stat-value { font-size: 2.5rem; font-weight: 800; color: var(--teal); }
.stat-unit { font-size: 1rem; color: var(--text-muted); }
.stat-desc { font-size: 0.8rem; color: var(--text-muted); text-align: center; margin-top: 0.5rem; max-width: 150px; }

/* Timeline */
.timeline-section { padding: 5rem 2rem; max-width: 1000px; margin: 0 auto; }
.timeline-items { display: flex; flex-direction: column; gap: 2rem; }
.timeline-item {
  display: grid; grid-template-columns: 150px 1fr 200px; gap: 2rem; align-items: center;
}
.timeline-duration { font-size: 1.5rem; font-weight: 700; color: var(--teal); }
.timeline-bar { height: 8px; background: rgba(0,180,216,0.2); border-radius: 4px; position: relative; overflow: hidden; }
.timeline-bar-fill { height: 100%; background: var(--teal); border-radius: 4px; }
.timeline-label { text-align: right; font-size: 0.9rem; color: var(--text-muted); }

/* Accordion */
.accordion-section { padding: 5rem 2rem; max-width: 1000px; margin: 0 auto; }
.accordion-item { background: var(--charcoal); border-radius: 10px; margin-bottom: 1rem; overflow: hidden; border: 1px solid rgba(255,255,255,0.05); }
.accordion-header {
  width: 100%; background: none; border: none; color: var(--white);
  padding: 1.25rem 1.5rem; display: flex; justify-content: space-between;
  align-items: center; cursor: pointer; font-size: 1.05rem; font-weight: 600;
  transition: background 0.2s;
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-header svg { width: 20px; height: 20px; transition: transform 0.3s; color: var(--teal); }
.accordion-item.open .accordion-header svg { transform: rotate(180deg); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.accordion-body-inner { padding: 1.25rem 1.5rem; color: var(--text-muted); line-height: 1.7; }
.accordion-item.open .accordion-body { max-height: 300px; }

/* Data Lifecycle Diagram */
.lifecycle-section { padding: 5rem 2rem; background: var(--charcoal); }
.lifecycle-container { max-width: 1200px; margin: 0 auto; }
.lifecycle-title { text-align: center; margin-bottom: 3rem; }
.lifecycle-flow { display: flex; justify-content: center; align-items: center; gap: 0; flex-wrap: wrap; }
.lifecycle-step {
  background: var(--navy-dark); border: 1px solid rgba(0,180,216,0.3);
  border-radius: 10px; padding: 1.5rem 2rem; text-align: center;
  min-width: 160px; position: relative;
}
.lifecycle-step h4 { color: var(--teal); margin-bottom: 0.3rem; }
.lifecycle-step p { font-size: 0.85rem; color: var(--text-muted); }
.lifecycle-arrow { width: 40px; height: 2px; background: var(--teal); position: relative; }
.lifecycle-arrow::after { content: ''; position: absolute; right: 0; top: -4px; border: 5px solid transparent; border-left-color: var(--teal); }

/* Testimonials */
.testimonials-section { padding: 5rem 2rem; max-width: 1200px; margin: 0 auto; }
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track { display: flex; transition: transform 0.4s ease; }
.testimonial-card {
  min-width: 100%; padding: 2.5rem; background: var(--charcoal);
  border-radius: 12px; border: 1px solid rgba(255,255,255,0.05);
}
.testimonial-card p { font-size: 1.15rem; font-style: italic; color: var(--white); margin-bottom: 1.5rem; line-height: 1.8; }
.testimonial-author { display: flex; align-items: center; gap: 1rem; }
.testimonial-avatar { width: 48px; height: 48px; border-radius: 50%; background: var(--teal); display: flex; align-items: center; justify-content: center; font-weight: 700; color: var(--navy); }
.testimonial-info h4 { font-size: 0.95rem; }
.testimonial-info span { font-size: 0.85rem; color: var(--text-muted); }
.carousel-dots { display: flex; justify-content: center; gap: 0.5rem; margin-top: 2rem; }
.carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,0.2); border: none; cursor: pointer; transition: all 0.2s; }
.carousel-dot.active { background: var(--teal); }

/* Security Page */
.security-hero { padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%); text-align: center; }
.security-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.security-feature {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s;
}
.security-feature:hover { border-color: rgba(0,180,216,0.4); }
.security-icon { width: 56px; height: 56px; background: rgba(0,180,216,0.15); border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 1.25rem; }
.security-icon svg { width: 28px; height: 28px; color: var(--teal); }
.security-feature h3 { font-size: 1.05rem; margin-bottom: 0.5rem; }
.security-feature p { color: var(--text-muted); font-size: 0.9rem; }

/* Integration Page */
.integration-hero { padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%); text-align: center; }
.integration-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.5rem; }
.integration-benefit {
  background: var(--charcoal); border-radius: 12px; padding: 1.5rem;
  display: flex; align-items: flex-start; gap: 1rem; border: 1px solid rgba(255,255,255,0.05);
}
.integration-benefit svg { width: 24px; height: 24px; color: var(--green); flex-shrink: 0; margin-top: 0.2rem; }
.integration-benefit h4 { font-size: 1rem; margin-bottom: 0.3rem; }
.integration-benefit p { color: var(--text-muted); font-size: 0.9rem; }
.tab-panel-graphic { background: var(--navy); border-radius: 12px; padding: 2.5rem; margin-top: 2rem; text-align: center; }
.tab-panel-graphic h3 { font-size: 1.3rem; margin-bottom: 1rem; }
.tab-panel-graphic p { color: var(--text-muted); }

/* Demo Form */
.demo-section { padding: 6rem 2rem; max-width: 800px; margin: 0 auto; }
.demo-form {
  background: var(--charcoal); border-radius: 16px; padding: 3rem;
  border: 1px solid rgba(255,255,255,0.05);
}
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-bottom: 1.5rem; }
.form-group { display: flex; flex-direction: column; gap: 0.5rem; }
.form-group.full { grid-column: 1 / -1; }
.form-group label { font-size: 0.9rem; font-weight: 500; color: var(--text-muted); }
.form-group input, .form-group select, .form-group textarea {
  background: var(--navy); border: 1px solid rgba(255,255,255,0.1);
  color: var(--white); padding: 0.85rem 1rem; border-radius: 6px;
  font-size: 1rem; transition: border-color 0.2s;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus { outline: none; border-color: var(--teal); }
.form-group textarea { min-height: 120px; resize: vertical; }
.form-error { color: #FF6B6B; font-size: 0.8rem; display: none; margin-top: 0.25rem; }
.form-group.error input, .form-group.error select, .form-group.error textarea { border-color: #FF6B6B; }
.form-group.error .form-error { display: block; }
.form-success { display: none; text-align: center; padding: 3rem; }
.form-success.show { display: block; }
.form-success svg { width: 64px; height: 64px; color: var(--green); margin: 0 auto 1.5rem; }
.form-success h3 { font-size: 1.5rem; margin-bottom: 0.75rem; }
.form-success p { color: var(--text-muted); }

/* Support Contact */
.support-section { padding: 4rem 2rem; background: var(--charcoal); }
.support-container { max-width: 1000px; margin: 0 auto; text-align: center; }
.support-regions { display: flex; justify-content: center; gap: 3rem; margin-top: 2rem; flex-wrap: wrap; }
.region-card { background: var(--navy); border-radius: 10px; padding: 1.5rem 2rem; min-width: 200px; }
.region-card h4 { color: var(--teal); margin-bottom: 0.5rem; }
.region-card p { color: var(--text-muted); font-size: 0.9rem; }

/* Mobile Styles */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .hero-container { grid-template-columns: 1fr; text-align: center; }
  .hero h1 { font-size: 2.5rem; }
  .hero-subtitle { margin: 0 auto 2rem; }
  .hero-buttons { justify-content: center; }
  .culture-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .timeline-item { grid-template-columns: 1fr; gap: 0.5rem; text-align: center; }
  .timeline-label { text-align: center; }
  .form-grid { grid-template-columns: 1fr; }
  .stat-circle { width: 140px; height: 140px; }
  .demo-form { padding: 2rem; }
  .page-hero h1 { font-size: 2.2rem; }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 2rem; }
  .section-title { font-size: 1.8rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .stats-container { gap: 2rem; }
}

/* Mobile Menu */
.mobile-nav { display: none; position: fixed; top: 72px; left: 0; right: 0; background: var(--charcoal); padding: 1rem; border-bottom: 1px solid rgba(255,255,255,0.1); z-index: 999; }
.mobile-nav.open { display: block; }
.mobile-nav a { display: block; padding: 0.75rem 1rem; color: var(--white); border-radius: 6px; }
.mobile-nav a:hover { background: rgba(0,180,216,0.1); }

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-dark: #15295A;
  --charcoal: #1B2838;
  --teal: #00B4D8;
  --teal-dark: #0077B6;
  --green: #6CC24A;
  --dark-gray: #3C424B;
  --light-gray: #E8E8E8;
  --white: #FFFFFF;
  --text-muted: #A0AEC0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); background: var(--navy); color: var(--white); line-height: 1.6; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

/* Navigation */
.navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 42, 0.95); backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  padding: 0 2rem;
}
.nav-container {
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; height: 72px;
}
.nav-logo { font-size: 1.5rem; font-weight: 700; color: var(--white); display: flex; align-items: center; gap: 0.5rem; }
.nav-logo span { color: var(--teal); }
.nav-links { display: flex; align-items: center; gap: 2rem; }
.nav-dropdown { position: relative; }
.nav-dropdown-btn {
  background: none; border: none; color: var(--white); font-size: 0.95rem;
  cursor: pointer; display: flex; align-items: center; gap: 0.3rem; padding: 0.5rem 0;
  transition: color 0.2s;
}
.nav-dropdown-btn:hover { color: var(--teal); }
.nav-dropdown-btn svg { width: 12px; height: 12px; transition: transform 0.2s; }
.nav-dropdown:hover .nav-dropdown-btn svg { transform: rotate(180deg); }
.nav-dropdown-menu {
  position: absolute; top: 100%; left: 0; min-width: 200px;
  background: var(--charcoal); border-radius: 8px; padding: 0.5rem;
  opacity: 0; visibility: hidden; transform: translateY(10px);
  transition: all 0.2s; box-shadow: 0 10px 40px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.nav-dropdown-menu a {
  display: block; padding: 0.6rem 1rem; border-radius: 4px;
  transition: background 0.2s; font-size: 0.9rem;
}
.nav-dropdown-menu a:hover { background: rgba(0,180,216,0.15); color: var(--teal); }
.nav-cta {
  background: var(--teal); color: var(--navy); font-weight: 600;
  padding: 0.6rem 1.25rem; border-radius: 6px; border: none;
  cursor: pointer; font-size: 0.9rem; transition: background 0.2s;
}
.nav-cta:hover { background: var(--teal-dark); }
.mobile-menu-btn { display: none; background: none; border: none; color: var(--white); cursor: pointer; }

/* Hero */
.hero {
  min-height: 100vh; display: flex; align-items: center;
  background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  padding: 8rem 2rem 4rem; position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,180,216,0.12) 0%, transparent 60%);
}
.hero-container { max-width: 1400px; margin: 0 auto; width: 100%; display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.hero-content { position: relative; z-index: 1; }
.hero-badge {
  display: inline-block; background: rgba(0,180,216,0.15); color: var(--teal);
  padding: 0.4rem 1rem; border-radius: 20px; font-size: 0.85rem; font-weight: 500;
  margin-bottom: 1.5rem; border: 1px solid rgba(0,180,216,0.3);
}
.hero h1 { font-size: 3.5rem; font-weight: 800; line-height: 1.1; margin-bottom: 1.5rem; }
.hero h1 em { font-style: normal; color: var(--teal); }
.hero-subtitle { font-size: 1.2rem; color: var(--text-muted); margin-bottom: 2rem; max-width: 540px; }
.hero-buttons { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  background: var(--teal); color: var(--navy); font-weight: 600;
  padding: 0.9rem 1.75rem; border-radius: 6px; border: none;
  cursor: pointer; font-size: 1rem; transition: all 0.2s;
}
.btn-primary:hover { background: var(--teal-dark); transform: translateY(-2px); }
.btn-secondary {
  background: transparent; color: var(--white); font-weight: 600;
  padding: 0.9rem 1.75rem; border-radius: 6px; border: 1px solid rgba(255,255,255,0.3);
  cursor: pointer; font-size: 1rem; transition: all 0.2s;
}
.btn-secondary:hover { border-color: var(--teal); color: var(--teal); }
.hero-visual { position: relative; z-index: 1; }

/* Platform Ecosystem Diagram */
.platform-diagram {
  background: var(--charcoal); border-radius: 16px; padding: 2.5rem;
  border: 1px solid rgba(255,255,255,0.08);
}
.diagram-title { text-align: center; font-size: 1.1rem; color: var(--text-muted); margin-bottom: 2rem; text-transform: uppercase; letter-spacing: 2px; }
.diagram-nodes { display: flex; flex-direction: column; gap: 1.5rem; }
.diagram-row { display: flex; justify-content: center; gap: 1.5rem; flex-wrap: wrap; }
.diagram-node {
  background: var(--navy-dark); border: 1px solid rgba(0,180,216,0.3);
  border-radius: 10px; padding: 1rem 1.5rem; text-align: center;
  min-width: 180px; transition: all 0.3s;
}
.diagram-node:hover { border-color: var(--teal); transform: translateY(-3px); box-shadow: 0 8px 30px rgba(0,180,216,0.2); }
.diagram-node h4 { color: var(--teal); font-size: 0.9rem; margin-bottom: 0.3rem; }
.diagram-node p { font-size: 0.8rem; color: var(--text-muted); }
.diagram-connectors { display: flex; justify-content: center; padding: 0.5rem 0; }
.connector-line { width: 2px; height: 30px; background: linear-gradient(to bottom, var(--teal), transparent); }
.connector-branch { display: flex; gap: 2rem; }
.connector-h { width: 60px; height: 2px; background: linear-gradient(to right, transparent, var(--teal), transparent); }

/* Featured Banner */
.featured-banner {
  background: linear-gradient(90deg, var(--navy-dark), var(--charcoal));
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
  padding: 1.5rem 2rem;
}
.featured-inner {
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem;
}
.featured-label { color: var(--green); font-weight: 600; font-size: 0.9rem; text-transform: uppercase; letter-spacing: 1px; }
.featured-product { font-size: 1.2rem; font-weight: 700; }
.featured-tag { color: var(--text-muted); font-size: 0.9rem; }
.btn-learn {
  background: transparent; border: 1px solid var(--green); color: var(--green);
  padding: 0.5rem 1.25rem; border-radius: 6px; cursor: pointer; font-size: 0.9rem;
  transition: all 0.2s;
}
.btn-learn:hover { background: var(--green); color: var(--navy); }

/* Use Cases */
.use-cases { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.section-label { color: var(--teal); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 0.75rem; }
.section-title { font-size: 2.5rem; font-weight: 700; margin-bottom: 1rem; }
.section-desc { color: var(--text-muted); max-width: 700px; margin-bottom: 3rem; font-size: 1.05rem; }
.use-case-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1.5rem; }
.use-case-card {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s; cursor: pointer;
}
.use-case-card:hover { border-color: rgba(0,180,216,0.4); transform: translateY(-4px); box-shadow: 0 15px 40px rgba(0,0,0,0.3); }
.use-case-card h3 { font-size: 1.1rem; margin-bottom: 0.75rem; color: var(--white); }
.use-case-card p { color: var(--text-muted); font-size: 0.95rem; }

/* Industry Tabs */
.industry-tabs-section { padding: 4rem 2rem; background: var(--charcoal); }
.industry-tabs-container { max-width: 1400px; margin: 0 auto; }
.tabs-nav { display: flex; gap: 0; border-bottom: 1px solid rgba(255,255,255,0.1); margin-bottom: 2rem; flex-wrap: wrap; }
.tab-btn {
  background: none; border: none; color: var(--text-muted);
  padding: 1rem 1.5rem; cursor: pointer; font-size: 0.95rem;
  border-bottom: 2px solid transparent; transition: all 0.2s;
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active { color: var(--teal); border-bottom-color: var(--teal); }
.tab-content { display: none; animation: fadeIn 0.3s ease; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel { background: var(--navy); border-radius: 12px; padding: 2rem; }
.tab-panel h3 { font-size: 1.3rem; margin-bottom: 1rem; }
.tab-panel p { color: var(--text-muted); }

/* Company Culture */
.company-culture { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.culture-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.culture-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 2rem; }
.stat-box { text-align: center; padding: 1.5rem; background: var(--charcoal); border-radius: 10px; }
.stat-number { font-size: 2.5rem; font-weight: 700; color: var(--teal); }
.stat-label { font-size: 0.85rem; color: var(--text-muted); margin-top: 0.3rem; }

/* Renewables CTA */
.renewables-cta {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--charcoal) 100%);
  padding: 5rem 2rem; text-align: center;
}
.cta-inner { max-width: 800px; margin: 0 auto; }
.cta-inner h2 { font-size: 2.5rem; margin-bottom: 1rem; }
.cta-inner p { color: var(--text-muted); margin-bottom: 2rem; font-size: 1.1rem; }

/* Footer */
.footer { background: var(--navy); border-top: 1px solid rgba(255,255,255,0.08); padding: 4rem 2rem 2rem; }
.footer-grid { max-width: 1400px; margin: 0 auto; display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: 3rem; margin-bottom: 3rem; }
.footer-brand p { color: var(--text-muted); margin-top: 1rem; font-size: 0.9rem; max-width: 280px; }
.footer-col h4 { font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 1.25rem; color: var(--text-muted); }
.footer-col ul li { margin-bottom: 0.75rem; }
.footer-col ul li a { color: var(--white); font-size: 0.95rem; transition: color 0.2s; }
.footer-col ul li a:hover { color: var(--teal); }
.footer-bottom {
  max-width: 1400px; margin: 0 auto; padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem;
}
.footer-legal { color: var(--text-muted); font-size: 0.85rem; }
.footer-portals { display: flex; gap: 1.5rem; }
.footer-portals a { color: var(--teal); font-size: 0.85rem; }

/* Cookie Banner */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 999;
  background: var(--charcoal); border-top: 1px solid rgba(255,255,255,0.1);
  padding: 1.25rem 2rem; display: none; align-items: center;
  justify-content: space-between; gap: 2rem; flex-wrap: wrap;
}
.cookie-banner.show { display: flex; }
.cookie-banner p { font-size: 0.9rem; color: var(--text-muted); }
.cookie-buttons { display: flex; gap: 1rem; }
.cookie-btn {
  padding: 0.5rem 1.25rem; border-radius: 6px; cursor: pointer;
  font-size: 0.9rem; transition: all 0.2s;
}
.cookie-accept { background: var(--teal); border: none; color: var(--navy); font-weight: 600; }
.cookie-decline { background: transparent; border: 1px solid rgba(255,255,255,0.3); color: var(--white); }

/* Platform Overview Page */
.page-hero {
  padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  text-align: center; position: relative;
}
.page-hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 50% 30%, rgba(0,180,216,0.1) 0%, transparent 60%);
}
.page-hero h1 { font-size: 3rem; font-weight: 800; margin-bottom: 1rem; position: relative; }
.page-hero p { font-size: 1.15rem; color: var(--text-muted); max-width: 600px; margin: 0 auto; position: relative; }

/* Benefits Grid */
.benefits-section { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.benefits-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; }
.benefit-card {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s;
}
.benefit-card:hover { border-color: rgba(0,180,216,0.4); }
.benefit-icon { width: 48px; height: 48px; background: rgba(0,180,216,0.15); border-radius: 10px; display: flex; align-items: center; justify-content: center; margin-bottom: 1rem; }
.benefit-icon svg { width: 24px; height: 24px; color: var(--teal); }
.benefit-card h3 { font-size: 1.1rem; margin-bottom: 0.5rem; }
.benefit-card p { color: var(--text-muted); font-size: 0.9rem; }

/* Stats Section */
.stats-section { padding: 4rem 2rem; background: var(--charcoal); }
.stats-container { max-width: 1000px; margin: 0 auto; display: flex; justify-content: center; gap: 4rem; flex-wrap: wrap; }
.stat-circle {
  width: 180px; height: 180px; border-radius: 50%;
  background: var(--navy); border: 3px solid var(--teal);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  position: relative;
}
.stat-circle::before {
  content: ''; position: absolute; inset: -8px;
  border-radius: 50%; border: 1px solid rgba(0,180,216,0.2);
}
.stat-value { font-size: 2.5rem; font-weight: 800; color: var(--teal); }
.stat-unit { font-size: 1rem; color: var(--text-muted); }
.stat-desc { font-size: 0.8rem; color: var(--text-muted); text-align: center; margin-top: 0.5rem; max-width: 150px; }

/* Timeline */
.timeline-section { padding: 5rem 2rem; max-width: 1000px; margin: 0 auto; }
.timeline-items { display: flex; flex-direction: column; gap: 2rem; }
.timeline-item {
  display: grid; grid-template-columns: 150px 1fr 200px; gap: 2rem; align-items: center;
}
.timeline-duration { font-size: 1.5rem; font-weight: 700; color: var(--teal); }
.timeline-bar { height: 8px; background: rgba(0,180,216,0.2); border-radius: 4px; position: relative; overflow: hidden; }
.timeline-bar-fill { height: 100%; background: var(--teal); border-radius: 4px; }
.timeline-label { text-align: right; font-size: 0.9rem; color: var(--text-muted); }

/* Accordion */
.accordion-section { padding: 5rem 2rem; max-width: 1000px; margin: 0 auto; }
.accordion-item { background: var(--charcoal); border-radius: 10px; margin-bottom: 1rem; overflow: hidden; border: 1px solid rgba(255,255,255,0.05); }
.accordion-header {
  width: 100%; background: none; border: none; color: var(--white);
  padding: 1.25rem 1.5rem; display: flex; justify-content: space-between;
  align-items: center; cursor: pointer; font-size: 1.05rem; font-weight: 600;
  transition: background 0.2s;
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-header svg { width: 20px; height: 20px; transition: transform 0.3s; color: var(--teal); }
.accordion-item.open .accordion-header svg { transform: rotate(180deg); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.accordion-body-inner { padding: 1.25rem 1.5rem; color: var(--text-muted); line-height: 1.7; }
.accordion-item.open .accordion-body { max-height: 300px; }

/* Data Lifecycle Diagram */
.lifecycle-section { padding: 5rem 2rem; background: var(--charcoal); }
.lifecycle-container { max-width: 1200px; margin: 0 auto; }
.lifecycle-title { text-align: center; margin-bottom: 3rem; }
.lifecycle-flow { display: flex; justify-content: center; align-items: center; gap: 0; flex-wrap: wrap; }
.lifecycle-step {
  background: var(--navy-dark); border: 1px solid rgba(0,180,216,0.3);
  border-radius: 10px; padding: 1.5rem 2rem; text-align: center;
  min-width: 160px; position: relative;
}
.lifecycle-step h4 { color: var(--teal); margin-bottom: 0.3rem; }
.lifecycle-step p { font-size: 0.85rem; color: var(--text-muted); }
.lifecycle-arrow { width: 40px; height: 2px; background: var(--teal); position: relative; }
.lifecycle-arrow::after { content: ''; position: absolute; right: 0; top: -4px; border: 5px solid transparent; border-left-color: var(--teal); }

/* Testimonials */
.testimonials-section { padding: 5rem 2rem; max-width: 1200px; margin: 0 auto; }
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track { display: flex; transition: transform 0.4s ease; }
.testimonial-card {
  min-width: 100%; padding: 2.5rem; background: var(--charcoal);
  border-radius: 12px; border: 1px solid rgba(255,255,255,0.05);
}
.testimonial-card p { font-size: 1.15rem; font-style: italic; color: var(--white); margin-bottom: 1.5rem; line-height: 1.8; }
.testimonial-author { display: flex; align-items: center; gap: 1rem; }
.testimonial-avatar { width: 48px; height: 48px; border-radius: 50%; background: var(--teal); display: flex; align-items: center; justify-content: center; font-weight: 700; color: var(--navy); }
.testimonial-info h4 { font-size: 0.95rem; }
.testimonial-info span { font-size: 0.85rem; color: var(--text-muted); }
.carousel-dots { display: flex; justify-content: center; gap: 0.5rem; margin-top: 2rem; }
.carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,0.2); border: none; cursor: pointer; transition: all 0.2s; }
.carousel-dot.active { background: var(--teal); }

/* Security Page */
.security-hero { padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%); text-align: center; }
.security-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.security-feature {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s;
}
.security-feature:hover { border-color: rgba(0,180,216,0.4); }
.security-icon { width: 56px; height: 56px; background: rgba(0,180,216,0.15); border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 1.25rem; }
.security-icon svg { width: 28px; height: 28px; color: var(--teal); }
.security-feature h3 { font-size: 1.05rem; margin-bottom: 0.5rem; }
.security-feature p { color: var(--text-muted); font-size: 0.9rem; }

/* Integration Page */
.integration-hero { padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%); text-align: center; }
.integration-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.5rem; }
.integration-benefit {
  background: var(--charcoal); border-radius: 12px; padding: 1.5rem;
  display: flex; align-items: flex-start; gap: 1rem; border: 1px solid rgba(255,255,255,0.05);
}
.integration-benefit svg { width: 24px; height: 24px; color: var(--green); flex-shrink: 0; margin-top: 0.2rem; }
.integration-benefit h4 { font-size: 1rem; margin-bottom: 0.3rem; }
.integration-benefit p { color: var(--text-muted); font-size: 0.9rem; }
.tab-panel-graphic { background: var(--navy); border-radius: 12px; padding: 2.5rem; margin-top: 2rem; text-align: center; }
.tab-panel-graphic h3 { font-size: 1.3rem; margin-bottom: 1rem; }
.tab-panel-graphic p { color: var(--text-muted); }

/* Demo Form */
.demo-section { padding: 6rem 2rem; max-width: 800px; margin: 0 auto; }
.demo-form {
  background: var(--charcoal); border-radius: 16px; padding: 3rem;
  border: 1px solid rgba(255,255,255,0.05);
}
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-bottom: 1.5rem; }
.form-group { display: flex; flex-direction: column; gap: 0.5rem; }
.form-group.full { grid-column: 1 / -1; }
.form-group label { font-size: 0.9rem; font-weight: 500; color: var(--text-muted); }
.form-group input, .form-group select, .form-group textarea {
  background: var(--navy); border: 1px solid rgba(255,255,255,0.1);
  color: var(--white); padding: 0.85rem 1rem; border-radius: 6px;
  font-size: 1rem; transition: border-color 0.2s;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus { outline: none; border-color: var(--teal); }
.form-group textarea { min-height: 120px; resize: vertical; }
.form-error { color: #FF6B6B; font-size: 0.8rem; display: none; margin-top: 0.25rem; }
.form-group.error input, .form-group.error select, .form-group.error textarea { border-color: #FF6B6B; }
.form-group.error .form-error { display: block; }
.form-success { display: none; text-align: center; padding: 3rem; }
.form-success.show { display: block; }
.form-success svg { width: 64px; height: 64px; color: var(--green); margin: 0 auto 1.5rem; }
.form-success h3 { font-size: 1.5rem; margin-bottom: 0.75rem; }
.form-success p { color: var(--text-muted); }

/* Support Contact */
.support-section { padding: 4rem 2rem; background: var(--charcoal); }
.support-container { max-width: 1000px; margin: 0 auto; text-align: center; }
.support-regions { display: flex; justify-content: center; gap: 3rem; margin-top: 2rem; flex-wrap: wrap; }
.region-card { background: var(--navy); border-radius: 10px; padding: 1.5rem 2rem; min-width: 200px; }
.region-card h4 { color: var(--teal); margin-bottom: 0.5rem; }
.region-card p { color: var(--text-muted); font-size: 0.9rem; }

/* Mobile Styles */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .hero-container { grid-template-columns: 1fr; text-align: center; }
  .hero h1 { font-size: 2.5rem; }
  .hero-subtitle { margin: 0 auto 2rem; }
  .hero-buttons { justify-content: center; }
  .culture-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .timeline-item { grid-template-columns: 1fr; gap: 0.5rem; text-align: center; }
  .timeline-label { text-align: center; }
  .form-grid { grid-template-columns: 1fr; }
  .stat-circle { width: 140px; height: 140px; }
  .demo-form { padding: 2rem; }
  .page-hero h1 { font-size: 2.2rem; }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 2rem; }
  .section-title { font-size: 1.8rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .stats-container { gap: 2rem; }
}

/* Mobile Menu */
.mobile-nav { display: none; position: fixed; top: 72px; left: 0; right: 0; background: var(--charcoal); padding: 1rem; border-bottom: 1px solid rgba(255,255,255,0.1); z-index: 999; }
.mobile-nav.open { display: block; }
.mobile-nav a { display: block; padding: 0.75rem 1rem; color: var(--white); border-radius: 6px; }
.mobile-nav a:hover { background: rgba(0,180,216,0.1); }

raw_arguments.content:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-dark: #15295A;
  --charcoal: #1B2838;
  --teal: #00B4D8;
  --teal-dark: #0077B6;
  --green: #6CC24A;
  --dark-gray: #3C424B;
  --light-gray: #E8E8E8;
  --white: #FFFFFF;
  --text-muted: #A0AEC0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); background: var(--navy); color: var(--white); line-height: 1.6; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

/* Navigation */
.navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 42, 0.95); backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  padding: 0 2rem;
}
.nav-container {
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; height: 72px;
}
.nav-logo { font-size: 1.5rem; font-weight: 700; color: var(--white); display: flex; align-items: center; gap: 0.5rem; }
.nav-logo span { color: var(--teal); }
.nav-links { display: flex; align-items: center; gap: 2rem; }
.nav-dropdown { position: relative; }
.nav-dropdown-btn {
  background: none; border: none; color: var(--white); font-size: 0.95rem;
  cursor: pointer; display: flex; align-items: center; gap: 0.3rem; padding: 0.5rem 0;
  transition: color 0.2s;
}
.nav-dropdown-btn:hover { color: var(--teal); }
.nav-dropdown-btn svg { width: 12px; height: 12px; transition: transform 0.2s; }
.nav-dropdown:hover .nav-dropdown-btn svg { transform: rotate(180deg); }
.nav-dropdown-menu {
  position: absolute; top: 100%; left: 0; min-width: 200px;
  background: var(--charcoal); border-radius: 8px; padding: 0.5rem;
  opacity: 0; visibility: hidden; transform: translateY(10px);
  transition: all 0.2s; box-shadow: 0 10px 40px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.nav-dropdown-menu a {
  display: block; padding: 0.6rem 1rem; border-radius: 4px;
  transition: background 0.2s; font-size: 0.9rem;
}
.nav-dropdown-menu a:hover { background: rgba(0,180,216,0.15); color: var(--teal); }
.nav-cta {
  background: var(--teal); color: var(--navy); font-weight: 600;
  padding: 0.6rem 1.25rem; border-radius: 6px; border: none;
  cursor: pointer; font-size: 0.9rem; transition: background 0.2s;
}
.nav-cta:hover { background: var(--teal-dark); }
.mobile-menu-btn { display: none; background: none; border: none; color: var(--white); cursor: pointer; }

/* Hero */
.hero {
  min-height: 100vh; display: flex; align-items: center;
  background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  padding: 8rem 2rem 4rem; position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,180,216,0.12) 0%, transparent 60%);
}
.hero-container { max-width: 1400px; margin: 0 auto; width: 100%; display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.hero-content { position: relative; z-index: 1; }
.hero-badge {
  display: inline-block; background: rgba(0,180,216,0.15); color: var(--teal);
  padding: 0.4rem 1rem; border-radius: 20px; font-size: 0.85rem; font-weight: 500;
  margin-bottom: 1.5rem; border: 1px solid rgba(0,180,216,0.3);
}
.hero h1 { font-size: 3.5rem; font-weight: 800; line-height: 1.1; margin-bottom: 1.5rem; }
.hero h1 em { font-style: normal; color: var(--teal); }
.hero-subtitle { font-size: 1.2rem; color: var(--text-muted); margin-bottom: 2rem; max-width: 540px; }
.hero-buttons { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  background: var(--teal); color: var(--navy); font-weight: 600;
  padding: 0.9rem 1.75rem; border-radius: 6px; border: none;
  cursor: pointer; font-size: 1rem; transition: all 0.2s;
}
.btn-primary:hover { background: var(--teal-dark); transform: translateY(-2px); }
.btn-secondary {
  background: transparent; color: var(--white); font-weight: 600;
  padding: 0.9rem 1.75rem; border-radius: 6px; border: 1px solid rgba(255,255,255,0.3);
  cursor: pointer; font-size: 1rem; transition: all 0.2s;
}
.btn-secondary:hover { border-color: var(--teal); color: var(--teal); }
.hero-visual { position: relative; z-index: 1; }

/* Platform Ecosystem Diagram */
.platform-diagram {
  background: var(--charcoal); border-radius: 16px; padding: 2.5rem;
  border: 1px solid rgba(255,255,255,0.08);
}
.diagram-title { text-align: center; font-size: 1.1rem; color: var(--text-muted); margin-bottom: 2rem; text-transform: uppercase; letter-spacing: 2px; }
.diagram-nodes { display: flex; flex-direction: column; gap: 1.5rem; }
.diagram-row { display: flex; justify-content: center; gap: 1.5rem; flex-wrap: wrap; }
.diagram-node {
  background: var(--navy-dark); border: 1px solid rgba(0,180,216,0.3);
  border-radius: 10px; padding: 1rem 1.5rem; text-align: center;
  min-width: 180px; transition: all 0.3s;
}
.diagram-node:hover { border-color: var(--teal); transform: translateY(-3px); box-shadow: 0 8px 30px rgba(0,180,216,0.2); }
.diagram-node h4 { color: var(--teal); font-size: 0.9rem; margin-bottom: 0.3rem; }
.diagram-node p { font-size: 0.8rem; color: var(--text-muted); }
.diagram-connectors { display: flex; justify-content: center; padding: 0.5rem 0; }
.connector-line { width: 2px; height: 30px; background: linear-gradient(to bottom, var(--teal), transparent); }
.connector-branch { display: flex; gap: 2rem; }
.connector-h { width: 60px; height: 2px; background: linear-gradient(to right, transparent, var(--teal), transparent); }

/* Featured Banner */
.featured-banner {
  background: linear-gradient(90deg, var(--navy-dark), var(--charcoal));
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
  padding: 1.5rem 2rem;
}
.featured-inner {
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem;
}
.featured-label { color: var(--green); font-weight: 600; font-size: 0.9rem; text-transform: uppercase; letter-spacing: 1px; }
.featured-product { font-size: 1.2rem; font-weight: 700; }
.featured-tag { color: var(--text-muted); font-size: 0.9rem; }
.btn-learn {
  background: transparent; border: 1px solid var(--green); color: var(--green);
  padding: 0.5rem 1.25rem; border-radius: 6px; cursor: pointer; font-size: 0.9rem;
  transition: all 0.2s;
}
.btn-learn:hover { background: var(--green); color: var(--navy); }

/* Use Cases */
.use-cases { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.section-label { color: var(--teal); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 0.75rem; }
.section-title { font-size: 2.5rem; font-weight: 700; margin-bottom: 1rem; }
.section-desc { color: var(--text-muted); max-width: 700px; margin-bottom: 3rem; font-size: 1.05rem; }
.use-case-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1.5rem; }
.use-case-card {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s; cursor: pointer;
}
.use-case-card:hover { border-color: rgba(0,180,216,0.4); transform: translateY(-4px); box-shadow: 0 15px 40px rgba(0,0,0,0.3); }
.use-case-card h3 { font-size: 1.1rem; margin-bottom: 0.75rem; color: var(--white); }
.use-case-card p { color: var(--text-muted); font-size: 0.95rem; }

/* Industry Tabs */
.industry-tabs-section { padding: 4rem 2rem; background: var(--charcoal); }
.industry-tabs-container { max-width: 1400px; margin: 0 auto; }
.tabs-nav { display: flex; gap: 0; border-bottom: 1px solid rgba(255,255,255,0.1); margin-bottom: 2rem; flex-wrap: wrap; }
.tab-btn {
  background: none; border: none; color: var(--text-muted);
  padding: 1rem 1.5rem; cursor: pointer; font-size: 0.95rem;
  border-bottom: 2px solid transparent; transition: all 0.2s;
}
.tab-btn:hover { color: var(--white); }
.tab-btn.active { color: var(--teal); border-bottom-color: var(--teal); }
.tab-content { display: none; animation: fadeIn 0.3s ease; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel { background: var(--navy); border-radius: 12px; padding: 2rem; }
.tab-panel h3 { font-size: 1.3rem; margin-bottom: 1rem; }
.tab-panel p { color: var(--text-muted); }

/* Company Culture */
.company-culture { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.culture-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.culture-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 2rem; }
.stat-box { text-align: center; padding: 1.5rem; background: var(--charcoal); border-radius: 10px; }
.stat-number { font-size: 2.5rem; font-weight: 700; color: var(--teal); }
.stat-label { font-size: 0.85rem; color: var(--text-muted); margin-top: 0.3rem; }

/* Renewables CTA */
.renewables-cta {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--charcoal) 100%);
  padding: 5rem 2rem; text-align: center;
}
.cta-inner { max-width: 800px; margin: 0 auto; }
.cta-inner h2 { font-size: 2.5rem; margin-bottom: 1rem; }
.cta-inner p { color: var(--text-muted); margin-bottom: 2rem; font-size: 1.1rem; }

/* Footer */
.footer { background: var(--navy); border-top: 1px solid rgba(255,255,255,0.08); padding: 4rem 2rem 2rem; }
.footer-grid { max-width: 1400px; margin: 0 auto; display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: 3rem; margin-bottom: 3rem; }
.footer-brand p { color: var(--text-muted); margin-top: 1rem; font-size: 0.9rem; max-width: 280px; }
.footer-col h4 { font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 1.25rem; color: var(--text-muted); }
.footer-col ul li { margin-bottom: 0.75rem; }
.footer-col ul li a { color: var(--white); font-size: 0.95rem; transition: color 0.2s; }
.footer-col ul li a:hover { color: var(--teal); }
.footer-bottom {
  max-width: 1400px; margin: 0 auto; padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem;
}
.footer-legal { color: var(--text-muted); font-size: 0.85rem; }
.footer-portals { display: flex; gap: 1.5rem; }
.footer-portals a { color: var(--teal); font-size: 0.85rem; }

/* Cookie Banner */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 999;
  background: var(--charcoal); border-top: 1px solid rgba(255,255,255,0.1);
  padding: 1.25rem 2rem; display: none; align-items: center;
  justify-content: space-between; gap: 2rem; flex-wrap: wrap;
}
.cookie-banner.show { display: flex; }
.cookie-banner p { font-size: 0.9rem; color: var(--text-muted); }
.cookie-buttons { display: flex; gap: 1rem; }
.cookie-btn {
  padding: 0.5rem 1.25rem; border-radius: 6px; cursor: pointer;
  font-size: 0.9rem; transition: all 0.2s;
}
.cookie-accept { background: var(--teal); border: none; color: var(--navy); font-weight: 600; }
.cookie-decline { background: transparent; border: 1px solid rgba(255,255,255,0.3); color: var(--white); }

/* Platform Overview Page */
.page-hero {
  padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  text-align: center; position: relative;
}
.page-hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 50% 30%, rgba(0,180,216,0.1) 0%, transparent 60%);
}
.page-hero h1 { font-size: 3rem; font-weight: 800; margin-bottom: 1rem; position: relative; }
.page-hero p { font-size: 1.15rem; color: var(--text-muted); max-width: 600px; margin: 0 auto; position: relative; }

/* Benefits Grid */
.benefits-section { padding: 5rem 2rem; max-width: 1400px; margin: 0 auto; }
.benefits-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; }
.benefit-card {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s;
}
.benefit-card:hover { border-color: rgba(0,180,216,0.4); }
.benefit-icon { width: 48px; height: 48px; background: rgba(0,180,216,0.15); border-radius: 10px; display: flex; align-items: center; justify-content: center; margin-bottom: 1rem; }
.benefit-icon svg { width: 24px; height: 24px; color: var(--teal); }
.benefit-card h3 { font-size: 1.1rem; margin-bottom: 0.5rem; }
.benefit-card p { color: var(--text-muted); font-size: 0.9rem; }

/* Stats Section */
.stats-section { padding: 4rem 2rem; background: var(--charcoal); }
.stats-container { max-width: 1000px; margin: 0 auto; display: flex; justify-content: center; gap: 4rem; flex-wrap: wrap; }
.stat-circle {
  width: 180px; height: 180px; border-radius: 50%;
  background: var(--navy); border: 3px solid var(--teal);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  position: relative;
}
.stat-circle::before {
  content: ''; position: absolute; inset: -8px;
  border-radius: 50%; border: 1px solid rgba(0,180,216,0.2);
}
.stat-value { font-size: 2.5rem; font-weight: 800; color: var(--teal); }
.stat-unit { font-size: 1rem; color: var(--text-muted); }
.stat-desc { font-size: 0.8rem; color: var(--text-muted); text-align: center; margin-top: 0.5rem; max-width: 150px; }

/* Timeline */
.timeline-section { padding: 5rem 2rem; max-width: 1000px; margin: 0 auto; }
.timeline-items { display: flex; flex-direction: column; gap: 2rem; }
.timeline-item {
  display: grid; grid-template-columns: 150px 1fr 200px; gap: 2rem; align-items: center;
}
.timeline-duration { font-size: 1.5rem; font-weight: 700; color: var(--teal); }
.timeline-bar { height: 8px; background: rgba(0,180,216,0.2); border-radius: 4px; position: relative; overflow: hidden; }
.timeline-bar-fill { height: 100%; background: var(--teal); border-radius: 4px; }
.timeline-label { text-align: right; font-size: 0.9rem; color: var(--text-muted); }

/* Accordion */
.accordion-section { padding: 5rem 2rem; max-width: 1000px; margin: 0 auto; }
.accordion-item { background: var(--charcoal); border-radius: 10px; margin-bottom: 1rem; overflow: hidden; border: 1px solid rgba(255,255,255,0.05); }
.accordion-header {
  width: 100%; background: none; border: none; color: var(--white);
  padding: 1.25rem 1.5rem; display: flex; justify-content: space-between;
  align-items: center; cursor: pointer; font-size: 1.05rem; font-weight: 600;
  transition: background 0.2s;
}
.accordion-header:hover { background: rgba(0,180,216,0.05); }
.accordion-header svg { width: 20px; height: 20px; transition: transform 0.3s; color: var(--teal); }
.accordion-item.open .accordion-header svg { transform: rotate(180deg); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.accordion-body-inner { padding: 1.25rem 1.5rem; color: var(--text-muted); line-height: 1.7; }
.accordion-item.open .accordion-body { max-height: 300px; }

/* Data Lifecycle Diagram */
.lifecycle-section { padding: 5rem 2rem; background: var(--charcoal); }
.lifecycle-container { max-width: 1200px; margin: 0 auto; }
.lifecycle-title { text-align: center; margin-bottom: 3rem; }
.lifecycle-flow { display: flex; justify-content: center; align-items: center; gap: 0; flex-wrap: wrap; }
.lifecycle-step {
  background: var(--navy-dark); border: 1px solid rgba(0,180,216,0.3);
  border-radius: 10px; padding: 1.5rem 2rem; text-align: center;
  min-width: 160px; position: relative;
}
.lifecycle-step h4 { color: var(--teal); margin-bottom: 0.3rem; }
.lifecycle-step p { font-size: 0.85rem; color: var(--text-muted); }
.lifecycle-arrow { width: 40px; height: 2px; background: var(--teal); position: relative; }
.lifecycle-arrow::after { content: ''; position: absolute; right: 0; top: -4px; border: 5px solid transparent; border-left-color: var(--teal); }

/* Testimonials */
.testimonials-section { padding: 5rem 2rem; max-width: 1200px; margin: 0 auto; }
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track { display: flex; transition: transform 0.4s ease; }
.testimonial-card {
  min-width: 100%; padding: 2.5rem; background: var(--charcoal);
  border-radius: 12px; border: 1px solid rgba(255,255,255,0.05);
}
.testimonial-card p { font-size: 1.15rem; font-style: italic; color: var(--white); margin-bottom: 1.5rem; line-height: 1.8; }
.testimonial-author { display: flex; align-items: center; gap: 1rem; }
.testimonial-avatar { width: 48px; height: 48px; border-radius: 50%; background: var(--teal); display: flex; align-items: center; justify-content: center; font-weight: 700; color: var(--navy); }
.testimonial-info h4 { font-size: 0.95rem; }
.testimonial-info span { font-size: 0.85rem; color: var(--text-muted); }
.carousel-dots { display: flex; justify-content: center; gap: 0.5rem; margin-top: 2rem; }
.carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,0.2); border: none; cursor: pointer; transition: all 0.2s; }
.carousel-dot.active { background: var(--teal); }

/* Security Page */
.security-hero { padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%); text-align: center; }
.security-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.security-feature {
  background: var(--charcoal); border-radius: 12px; padding: 1.75rem;
  border: 1px solid rgba(255,255,255,0.05); transition: all 0.3s;
}
.security-feature:hover { border-color: rgba(0,180,216,0.4); }
.security-icon { width: 56px; height: 56px; background: rgba(0,180,216,0.15); border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 1.25rem; }
.security-icon svg { width: 28px; height: 28px; color: var(--teal); }
.security-feature h3 { font-size: 1.05rem; margin-bottom: 0.5rem; }
.security-feature p { color: var(--text-muted); font-size: 0.9rem; }

/* Integration Page */
.integration-hero { padding: 10rem 2rem 5rem; background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%); text-align: center; }
.integration-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.5rem; }
.integration-benefit {
  background: var(--charcoal); border-radius: 12px; padding: 1.5rem;
  display: flex; align-items: flex-start; gap: 1rem; border: 1px solid rgba(255,255,255,0.05);
}
.integration-benefit svg { width: 24px; height: 24px; color: var(--green); flex-shrink: 0; margin-top: 0.2rem; }
.integration-benefit h4 { font-size: 1rem; margin-bottom: 0.3rem; }
.integration-benefit p { color: var(--text-muted); font-size: 0.9rem; }
.tab-panel-graphic { background: var(--navy); border-radius: 12px; padding: 2.5rem; margin-top: 2rem; text-align: center; }
.tab-panel-graphic h3 { font-size: 1.3rem; margin-bottom: 1rem; }
.tab-panel-graphic p { color: var(--text-muted); }

/* Demo Form */
.demo-section { padding: 6rem 2rem; max-width: 800px; margin: 0 auto; }
.demo-form {
  background: var(--charcoal); border-radius: 16px; padding: 3rem;
  border: 1px solid rgba(255,255,255,0.05);
}
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-bottom: 1.5rem; }
.form-group { display: flex; flex-direction: column; gap: 0.5rem; }
.form-group.full { grid-column: 1 / -1; }
.form-group label { font-size: 0.9rem; font-weight: 500; color: var(--text-muted); }
.form-group input, .form-group select, .form-group textarea {
  background: var(--navy); border: 1px solid rgba(255,255,255,0.1);
  color: var(--white); padding: 0.85rem 1rem; border-radius: 6px;
  font-size: 1rem; transition: border-color 0.2s;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus { outline: none; border-color: var(--teal); }
.form-group textarea { min-height: 120px; resize: vertical; }
.form-error { color: #FF6B6B; font-size: 0.8rem; display: none; margin-top: 0.25rem; }
.form-group.error input, .form-group.error select, .form-group.error textarea { border-color: #FF6B6B; }
.form-group.error .form-error { display: block; }
.form-success { display: none; text-align: center; padding: 3rem; }
.form-success.show { display: block; }
.form-success svg { width: 64px; height: 64px; color: var(--green); margin: 0 auto 1.5rem; }
.form-success h3 { font-size: 1.5rem; margin-bottom: 0.75rem; }
.form-success p { color: var(--text-muted); }

/* Support Contact */
.support-section { padding: 4rem 2rem; background: var(--charcoal); }
.support-container { max-width: 1000px; margin: 0 auto; text-align: center; }
.support-regions { display: flex; justify-content: center; gap: 3rem; margin-top: 2rem; flex-wrap: wrap; }
.region-card { background: var(--navy); border-radius: 10px; padding: 1.5rem 2rem; min-width: 200px; }
.region-card h4 { color: var(--teal); margin-bottom: 0.5rem; }
.region-card p { color: var(--text-muted); font-size: 0.9rem; }

/* Mobile Styles */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .hero-container { grid-template-columns: 1fr; text-align: center; }
  .hero h1 { font-size: 2.5rem; }
  .hero-subtitle { margin: 0 auto 2rem; }
  .hero-buttons { justify-content: center; }
  .culture-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .timeline-item { grid-template-columns: 1fr; gap: 0.5rem; text-align: center; }
  .timeline-label { text-align: center; }
  .form-grid { grid-template-columns: 1fr; }
  .stat-circle { width: 140px; height: 140px; }
  .demo-form { padding: 2rem; }
  .page-hero h1 { font-size: 2.2rem; }
}
@media (max-width: 480px) {
  .hero h1 { font-size: 2rem; }
  .section-title { font-size: 1.8rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .stats-container { gap: 2rem; }
}

/* Mobile Menu */
.mobile-nav { display: none; position: fixed; top: 72px; left: 0; right: 0; background: var(--charcoal); padding: 1rem; border-bottom: 1px solid rgba(255,255,255,0.1); z-index: 999; }
.mobile-nav.open { display: block; }
.mobile-nav a { display: block; padding: 0.75rem 1rem; color: var(--white); border-radius: 6px; }
.mobile-nav a:hover { background: rgba(0,180,216,0.1); }

